// Subscribe once, for example in the form constructor
menuStrip1.ItemClicked += MenuStrip1_ItemClicked;

private void MenuStrip1_ItemClicked(object sender, ToolStripItemClickedEventArgs e)
{
    MessageBox.Show("Clicked: " + e.ClickedItem.Text);
}

// Subscribe once, for example in the form constructor
menuStrip1.MenuActivate += MenuStrip1_MenuActivate;

private void MenuStrip1_MenuActivate(object sender, EventArgs e)
{
    this.Text = "Menu active";
}

// Subscribe once, for example in the form constructor
menuStrip1.MenuDeactivate += MenuStrip1_MenuDeactivate;

private void MenuStrip1_MenuDeactivate(object sender, EventArgs e)
{
    this.Text = "Menu closed";
}

// Subscribe once, for example in the form constructor
ctxMenu.Opening += CtxMenu_Opening;

private void CtxMenu_Opening(object sender, CancelEventArgs e)
{
    if (ctxMenu.SourceControl is TextBox box && box.ReadOnly)
    {
        e.Cancel = true;
    }
}

// Subscribe once, for example in the form constructor
ctxMenu.Opened += CtxMenu_Opened;

private void CtxMenu_Opened(object sender, EventArgs e)
{
    this.Text = "Menu opened";
}

// Subscribe once, for example in the form constructor
ctxMenu.Closing += CtxMenu_Closing;

private void CtxMenu_Closing(object sender, ToolStripDropDownClosingEventArgs e)
{
    if (e.CloseReason == ToolStripDropDownCloseReason.ItemClicked)
    {
        this.Text = "Item chosen";
    }
}

